    run([](auto& e,auto& f,auto&){word(f.payload,16,777);e.options.weak=true;const auto j=e.scan();check(j["candidates"][0]["match_strength"]=="weak_raw_469_candidate" && j["candidates"][0]["raw_469_byte_offsets"][0]==32 && j["identity_proven"]==false,"raw469 fallback is weak only");return 0;});
