    run([](auto& e,auto& f,auto&){e.scan_limits.sources=1;f.accesses.push_back(f.accesses[0]);const auto j=e.scan();check(f.reads==1 && f.descriptor_reads==1 && j["completion"]=="source_limit" && j["coverage_complete"]==false,"scan per-event source cap before descriptor/read");return 0;});
