    const auto resolved=std::filesystem::weakly_canonical(dir);check(resolved.parent_path()==std::filesystem::weakly_canonical(parent) && resolved.filename().string().rfind("sm2vr-scan-cpu-",0)==0,"scan fixture cleanup bounded");std::filesystem::remove_all(resolved);std::cout<<"replay scan production CPU paths PASS\n";return 0;
